@app.post("/api/v1/customers/segment")
@response_time.labels(endpoint="customer_segmentation").time()
async def segment_customers(
    request: SegmentationRequest,
    credentials: HTTPAuthorizationCredentials = Depends(security),
):
    """Segment customers into groups."""
    request_counter.labels(endpoint="customer_segmentation").inc()

    try:
        # Verify authentication
        if not verify_token(credentials.credentials):
            raise HTTPException(status_code=401, detail="Invalid token")

        # Get customer data
        customer_data = data_processor.get_customer_data(request.customer_ids)

        # Perform segmentation
        segments = customer_segmentation.predict(customer_data)

        # Cache results
        cache_key = f"segments:{hash(tuple(request.customer_ids))}"
        redis_client.setex(cache_key, 3600, json.dumps(segments))

        return {"segments": segments, "timestamp": datetime.now().isoformat()}

    except Exception as e:
        logger.error(f"Customer segmentation failed: {str(e)}")
        raise HTTPException(status_code=500, detail=str(e))
```

Generate product recommendations for customer.

```python
@app.post("/api/v1/recommendations/generate")
@response_time.labels(endpoint="recommendations").time()
async def generate_recommendations(
    request: RecommendationRequest,
    credentials: HTTPAuthorizationCredentials = Depends(security),
):
    """Generate product recommendations for customer."""
    request_counter.labels(endpoint="recommendations").inc()

    try:
        # Verify authentication
        if not verify_token(credentials.credentials):
            raise HTTPException(status_code=401, detail="Invalid token")

        # Check cache first
        cache_key = f"recommendations:{request.customer_id}"
        cached_recommendations = redis_client.get(cache_key)

        if cached_recommendations:
            return json.loads(cached_recommendations)

        # Generate recommendations
        recommendations = recommendation_system.get_recommendations(
            request.customer_id, request.product_count
        )

        # Cache results
        redis_client.setex(cache_key, 1800, json.dumps(recommendations))

        return recommendations

    except Exception as e:
        logger.error(f"Recommendation generation failed: {str(e)}")
        raise HTTPException(status_code=500, detail=str(e))
```

Comprehensive customer analysis.

```python
@app.post("/api/v1/customers/analyze")
@response_time.labels(endpoint="customer_analysis").time()
async def analyze_customer(
    customer_data: CustomerData,
    credentials: HTTPAuthorizationCredentials = Depends(security),
):
    """Comprehensive customer analysis."""
    request_counter.labels(endpoint="customer_analysis").inc()

    try:
        # Verify authentication
        if not verify_token(credentials.credentials):
            raise HTTPException(status_code=401, detail="Invalid token")

        # Perform comprehensive analysis
        analysis = {
            "customer_id": customer_data.customer_id,
            "segment": customer_segmentation.predict_single(customer_data),
            "lifetime_value": data_processor.calculate_lifetime_value(customer_data),
            "churn_risk": data_processor.calculate_churn_risk(customer_data),
            "recommendations": recommendation_system.get_recommendations(
                customer_data.customer_id, 5
            ),
            "analysis_timestamp": datetime.now().isoformat(),
        }

        return analysis

    except Exception as e:
        logger.error(f"Customer analysis failed: {str(e)}")
        raise HTTPException(status_code=500, detail=str(e))
```

